export function plan(gamma:number,modelB:number){const immediate=[1,0],continuation=[2,modelB],imagined=immediate.map((x,i)=>x+gamma*continuation[i]);const chosen=imagined[0]>=imagined[1]?0:1;return {gamma,immediate,continuation,imagined,chosen,actual:[1+gamma*2,gamma*4]};}
export function run(mode:number){return plan(mode===2?.5:1,mode===1?0:4);}

{r.immediate.map((a,i)=><g key={i}><text x="16" y={31+i*56}>{i===0?'A':'B'}</text><path d={`M38 ${26+i*56} H214`} className={s.line}/><circle cx="62" cy={26+i*56} r="17" className={s.box}/><circle cx="132" cy={26+i*56} r="17" className={s.box}/><text x="62" y={31+i*56} textAnchor="middle">{a}</text><text x="132" y={31+i*56} textAnchor="middle">{r.continuation[i]}</text><text x="224" y={31+i*56}>={show(r.imagined[i])}</text></g>)}<text x="145" y="119" textAnchor="middle">γ={r.gamma} · Plan {r.chosen===0?'A':'B'} · Actual {r.actual.join(',')}</text>
